"""Reports and exports (/api/v1/reports): generated by the results worker."""

from __future__ import annotations

from fastapi import APIRouter
from sqlalchemy import select

from parallel_core.access import Action, require_case, require_project, visible_case_ids
from parallel_core.audit import record as audit
from parallel_core.jobs import TASK_REPORT, celery_app
from parallel_core.models import Comparison, Report, SimulationRun, SourceAsset
from parallel_core.settings import get_settings
from parallel_core.storage import get_storage

from ..deps import DB, CurrentUser
from ..errors import ApiError
from ..schemas import ReportIn, ReportOut, SignedUrlOut

router = APIRouter(tags=["reports"])
FILES = {"report.pdf": "pdf_key", "metrics.csv": "csv_key", "manifest.json": "json_key"}


def _case_ref(rep: Report) -> dict:
    """Audit detail that keeps case-report events visible only to the case's assignees."""
    return {"case_id": rep.case_id} if rep.case_id else {}


def enqueue(db, report: Report) -> None:
    db.commit()
    if get_settings().task_always_eager:
        from parallel_results.generate import generate_report

        generate_report(report.id)
        db.refresh(report)
        return
    celery_app.send_task(TASK_REPORT, args=[report.id])


@router.post("/projects/{project_id}/reports", response_model=ReportOut, status_code=201)
def create(project_id: str, body: ReportIn, user: CurrentUser, db: DB):
    if body.kind == "case":
        if not body.case_id:
            raise ApiError(422, "case_required", "A case report needs case_id")
        case = require_case(db, user, body.case_id, Action.edit)
        if case.project_id != project_id:
            raise ApiError(404, "not_found", "Case not found")
        require_project(db, user, project_id)
    else:
        require_project(db, user, project_id, Action.edit)
    run_ids = list(dict.fromkeys(body.run_ids))
    if body.kind == "comparison":
        comp = db.get(Comparison, body.comparison_id) if body.comparison_id else None
        if comp is None or comp.project_id != project_id:
            raise ApiError(404, "not_found", "Comparison not found")
        run_ids = list(comp.run_ids)
    elif body.kind == "project" and not run_ids:
        raise ApiError(422, "runs_required", "Select at least one completed run")
    for rid in run_ids:
        r = db.get(SimulationRun, rid)
        if r is None or r.project_id != project_id:
            raise ApiError(404, "not_found", f"Run {rid} not found in this project")
        if r.case_id is not None:
            require_case(db, user, r.case_id)
            if body.kind != "case" or body.case_id != r.case_id:
                raise ApiError(422, "case_run", f"Run {rid} belongs to a case; include it in that case's report")
        if r.state != "completed":
            raise ApiError(
                422, "run_not_completed", f"Run {rid} is {r.state}; reports cover completed runs only"
            )
    for aid in body.figure_asset_ids:
        a = db.get(SourceAsset, aid)
        if a is None or a.project_id != project_id:
            raise ApiError(404, "not_found", f"Figure asset {aid} not found")
        if a.kind != "image" or a.sensitivity != "normal":
            raise ApiError(
                422,
                "figure_not_allowed",
                "Figures must be non-evidence images (original evidence media is never embedded)",
            )
    if body.narrative and not body.narrative_origin:
        raise ApiError(
            422,
            "narrative_origin_required",
            "State whether the narrative was written manually or drafted with AI assistance and adopted",
        )
    rep = Report(
        project_id=project_id,
        kind=body.kind,
        title=body.title,
        status="queued",
        run_ids=run_ids,
        comparison_id=body.comparison_id if body.kind == "comparison" else None,
        case_id=body.case_id if body.kind == "case" else None,
        narrative=body.narrative,
        narrative_origin=body.narrative_origin if body.narrative else None,
        author_id=user.id,
        manifest={"request": {"figure_asset_ids": body.figure_asset_ids}},
    )
    db.add(rep)
    db.flush()
    audit(
        db,
        action="report.requested",
        object_type="report",
        object_id=rep.id,
        actor_id=user.id,
        project_id=project_id,
        details={"kind": body.kind, "runs": len(run_ids), "narrative_origin": rep.narrative_origin, **_case_ref(rep)},
    )
    enqueue(db, rep)
    return rep


@router.get("/projects/{project_id}/reports", response_model=list[ReportOut])
def list_(project_id: str, user: CurrentUser, db: DB):
    require_project(db, user, project_id)
    cases = visible_case_ids(db, user, project_id)
    rows = db.scalars(
        select(Report).where(Report.project_id == project_id).order_by(Report.created_at.desc())
    ).all()
    return [r for r in rows if r.case_id is None or r.case_id in cases]


def _get(db, user, report_id: str) -> Report:
    rep = db.get(Report, report_id)
    if rep is None:
        raise ApiError(404, "not_found", "Report not found")
    require_project(db, user, rep.project_id)
    if rep.kind == "case" and rep.case_id:
        require_case(db, user, rep.case_id)
    return rep


@router.get("/reports/{report_id}", response_model=ReportOut)
def get(report_id: str, user: CurrentUser, db: DB):
    return _get(db, user, report_id)


@router.get("/reports/{report_id}/files/{name}", response_model=SignedUrlOut)
def file_url(report_id: str, name: str, user: CurrentUser, db: DB):
    rep = _get(db, user, report_id)
    if name not in FILES:
        raise ApiError(404, "not_found", f"Unknown report file {name}")
    key = getattr(rep, FILES[name])
    if rep.status != "completed" or not key:
        raise ApiError(409, "report_not_ready", f"Report is {rep.status}")
    audit(
        db,
        action="report.downloaded",
        object_type="report",
        object_id=rep.id,
        actor_id=user.id,
        project_id=rep.project_id,
        details={"file": name, **_case_ref(rep)},
    )
    return SignedUrlOut(
        url=get_storage().signed_url(key, f"{rep.title[:60]}-{name}"),
        expires_in_s=get_settings().signed_url_seconds,
    )


@router.post("/reports/{report_id}/regenerate", response_model=ReportOut)
def regenerate(report_id: str, user: CurrentUser, db: DB):
    rep = _get(db, user, report_id)
    if rep.kind == "case" and rep.case_id:
        require_case(db, user, rep.case_id, Action.edit)
    else:
        require_project(db, user, rep.project_id, Action.edit)
    if rep.status not in ("failed", "completed"):
        raise ApiError(409, "report_busy", f"Report is {rep.status}")
    rep.status = "queued"
    audit(
        db,
        action="report.regenerated",
        object_type="report",
        object_id=rep.id,
        actor_id=user.id,
        project_id=rep.project_id,
        details=_case_ref(rep),
    )
    enqueue(db, rep)
    return rep
